/** Preview URL for a region page key. */
function nexxi_studio_page_url( $page ) {
	switch ( $page ) {
		case 'home': return home_url( '/' );
		case 'shop': return nexxi_kids_shop_url();
		case 'flash': return nexxi_kids_flash_url();
		case 'account': return function_exists( 'wc_get_page_permalink' ) ? wc_get_page_permalink( 'myaccount' ) : home_url( '/' );
		case 'product':
			$ids = function_exists( 'wc_get_products' ) ? wc_get_products( array( 'limit' => 1, 'status' => 'publish', 'return' => 'ids' ) ) : array();
			return $ids ? get_permalink( $ids[0] ) : nexxi_kids_shop_url();
	}
	return '';
}

