function nexxi_studio_menu_defaults() {
	return array(
		1 => array( 'Trang Chủ', 'trang-chu', '', '' ),
		2 => array( 'Giới Thiệu', 'gioi-thieu', '', '' ),
		3 => array( 'Sản Phẩm', 'san-pham', 'Bé Yêu', 'soft' ),
		4 => array( 'Flash Sale', 'flash-sale', '⚡ Hot', 'hot' ),
		5 => array( 'Bảng Size', 'bang-size-cho-be', '', '' ),
		6 => array( 'Liên Hệ', 'lien-he', '', '' ),
		7 => array( '', '', '', '' ),
		8 => array( '', '', '', '' ),
	);
}

/** Menu items after edits: [label, path, url (custom or ''), badge, style]. */
function nexxi_studio_menu_items() {
	$items = array();
	foreach ( nexxi_studio_menu_defaults() as $n => $def ) {
		if ( '1' === nexxi_studio_opt( "menu_{$n}_hide" ) ) { continue; }
		$label = trim( nexxi_studio_opt( "menu_{$n}_label", $def[0] ) );
		if ( '' === $label ) { continue; }
		$items[] = array( $label, $def[1] ? $def[1] : 'custom-' . $n, nexxi_studio_url( nexxi_studio_opt( "menu_{$n}_url" ) ), trim( nexxi_studio_opt( "menu_{$n}_badge", $def[2] ) ), nexxi_studio_opt( "menu_{$n}_style", $def[3] ? $def[3] : 'soft' ) );
	}
	return $items;
}

function nexxi_studio_nbsp( $text ) {
	return str_replace( ' ', '&nbsp;', esc_html( $text ) );
}

/** Header edits (ticker, logo, label, menu, search). Runs before the shared header wiring. */
function nexxi_studio_header( $html ) {
	$el = nexxi_dom_locate( $html, '<header' );
	if ( ! $el ) { return $html; }
	$header = substr( $html, $el['start'], $el['end'] - $el['start'] );

	// Ticker.
	$ticker = nexxi_dom_locate( $header, '<div class="w-full bg-secondary-fixed' );
	if ( $ticker ) {
		$header = nexxi_dom_set_attr( $header, '<div class="w-full bg-secondary-fixed', 'data-nxr', 'header-ticker' );
		$lines = preg_split( '~\R~u', nexxi_studio_value( 'header-ticker__lines' ) );
		$lines = is_array( $lines ) ? array_values( array_filter( array_map( 'trim', $lines ) ) ) : array();
		if ( $lines ) {
			$spans = '';
			for ( $n = 0, $count = max( 4, count( $lines ) ); $n < $count; $n++ ) {
				$spans .= '<span class="inline-flex items-center gap-1.5 shrink-0">' . esc_html( $lines[ $n % count( $lines ) ] ) . '</span>';
			}
			$header = nexxi_dom_set_attr( $header, 'animate-marquee', 'style', 'width:max-content;animation-duration:38s;' );
			$header = nexxi_dom_set_inner( $header, 'animate-marquee', $spans . $spans );
		}
	}

	// Brand: logo (header + footer use the same file) and label.
	$header = nexxi_dom_set_attr( $header, '<div class="flex items-center gap-space-md shrink-0', 'data-nxr', 'header-brand' );
	$label = nexxi_dom_locate( $header, '<span class="font-label-sm text-label-sm text-secondary tracking-normal' );
	if ( $label ) {
		$header = substr( $header, 0, $label['start'] ) . preg_replace( '~^<span~', '<span data-nxe="header-brand__label"', substr( $header, $label['start'], $label['open_end'] - $label['start'] ) ) . nexxi_studio_t( 'header-brand__label' ) . substr( $header, $label['inner_end'] );
	}

	// Menu.
	$nav = nexxi_dom_locate( $header, '<nav' );
	if ( $nav ) {
		$base = 'px-space-md py-space-xs rounded-full font-label-lg text-label-lg text-on-surface-variant hover:text-on-surface hover:bg-surface-container-highest transition-all duration-200';
		$badges = array(
			'soft' => 'text-[10px] bg-tertiary-fixed text-on-tertiary-fixed px-1.5 py-0.5 rounded-full font-bold',
			'hot'  => 'inline-flex items-center px-1.5 py-0.2 rounded-full text-[10px] font-bold bg-secondary text-on-secondary animate-pulse',
			'pink' => 'text-[10px] bg-secondary-fixed text-on-secondary-fixed px-1.5 py-0.5 rounded-full font-bold',
		);
		$links = '';
		foreach ( nexxi_studio_menu_items() as $item ) {
			list( $text, $path, $url, $badge, $style ) = $item;
			$class = $badge ? 'relative ' . $base . ' flex items-center gap-1.5' : $base;
			$href = $url ? ' href="' . esc_url( $url ) . '" data-href-fixed="1"' : ' href="#"';
			$links .= '<a class="' . esc_attr( $class ) . '" data-path="' . esc_attr( $path ) . '"' . $href . '>' . nexxi_studio_nbsp( $text ) . ( $badge ? ' <span class="' . esc_attr( isset( $badges[ $style ] ) ? $badges[ $style ] : $badges['soft'] ) . '">' . nexxi_studio_nbsp( $badge ) . '</span>' : '' ) . '</a>';
		}
		$open = substr( $header, $nav['start'], $nav['open_end'] - $nav['start'] );
		$open = nexxi_dom_tag_with_attr( $open, 'data-nxr', 'header-menu' );
		$header = substr( $header, 0, $nav['start'] ) . $open . $links . substr( $header, $nav['inner_end'] );
	}

	// Search.
	$header = nexxi_dom_set_attr( $header, '<div class="hidden md:flex items-center bg-surface-container-low rounded-full', 'data-nxr', 'header-search' );
	$header = nexxi_dom_each( $header, '<input', static function ( $outer ) {
		$outer = nexxi_dom_tag_with_attr( $outer, 'placeholder', nexxi_studio_value( 'header-search__p' ) );
		return preg_replace( '~^<input\b~', '<input data-nxp="header-search__p"', $outer, 1 );
	} );

	$html = substr( $html, 0, $el['start'] ) . $header . substr( $html, $el['end'] );

	// Logo everywhere (header + footer).
	$html = str_replace( '<img alt="logo.jpg"', '<img data-nxi="header-brand__logo" alt="logo.jpg"', $html );
	$logo = nexxi_studio_changed( 'header-brand__logo' );
	if ( $logo ) {
		$html = str_replace( array( '{{STITCH_ASSET}}/images/logo.jpg', '{{STITCH_ASSET}}/images/logo-transparent.png' ), esc_url( $logo ), $html );
	} else {
		$html = str_replace( '{{STITCH_ASSET}}/images/logo.jpg', '{{STITCH_ASSET}}/images/logo-transparent.png', $html );
	}
	return $html;
}

/* ------------------------------------------------------------------ footer */

/** The approved home footer, reused on every screen so one edit applies everywhere. */
function nexxi_studio_shared_footer() {
	static $footer = null;
	if ( null === $footer ) {
		$file = get_template_directory() . '/assets/stitch/pages/index.html';
		$footer = is_readable( $file ) ? nexxi_dom_get_outer( file_get_contents( $file ), '<footer' ) : ''; // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	}
	return $footer;
}

