/** original hex => new hex for every changed colour. */
function nexxi_studio_color_map() {
	$map = array();
	foreach ( nexxi_studio_colors() as $key => $color ) {
		$value = sanitize_hex_color( nexxi_studio_opt( $key ) );
		if ( $value && strtolower( $value ) !== $color[2] ) { $map[ $color[2] ] = strtolower( $value ); }
	}
	return $map;
}

function nexxi_studio_apply_colors( $html ) {
	foreach ( nexxi_studio_colors() as $key => $color ) {
		$value = sanitize_hex_color( nexxi_studio_opt( $key ) );
		if ( ! $value || strtolower( $value ) === $color[2] ) { continue; }
		foreach ( $color[1] as $token ) {
			$html = preg_replace( '~("' . preg_quote( $token, '~' ) . '":\s*")#[0-9a-fA-F]{6}(")~', '${1}' . $value . '${2}', $html, 1 );
		}
	}
	return $html;
}

/** Stitch stylesheet tag; always inlined with data-no-optimize so LiteSpeed Cache never delays or breaks it. */
function nexxi_studio_stylesheet_tag( $url, $file ) {
	if ( ! is_readable( $file ) ) { return '<link data-no-optimize="1" rel="stylesheet" href="' . esc_url( $url ) . '">'; }
	$css = file_get_contents( $file ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
	$map = nexxi_studio_color_map();
	if ( $map ) {
		$css = str_ireplace( array_keys( $map ), array_values( $map ), $css );
	}
	return '<style id="nexxi-stitch-css" data-no-optimize="1">' . $css . '</style>';
}

/* ------------------------------------------------------------------ fonts & custom font uploads */

/** Allow uploading .woff2, .woff, .ttf, .otf font files in WordPress Media Library / Customizer. */
function nexxi_studio_font_mime_types() {
	return array(
		'woff2' => 'font/woff2',
		'woff'  => 'font/woff',
		'ttf'   => 'font/ttf',
		'otf'   => 'font/otf',
	);
}
add_filter( 'upload_mimes', static function ( $mimes ) {
	if ( current_user_can( 'edit_theme_options' ) || current_user_can( 'upload_files' ) ) {
		foreach ( nexxi_studio_font_mime_types() as $ext => $mime ) {
			$mimes[ $ext ] = $mime;
		}
	}
	return $mimes;
} );
add_filter( 'wp_check_filetype_and_ext', static function ( $data, $file, $filename ) {
	if ( ! empty( $data['ext'] ) && ! empty( $data['type'] ) ) {
		return $data;
	}
	$ext = strtolower( pathinfo( (string) $filename, PATHINFO_EXTENSION ) );
	$allowed = nexxi_studio_font_mime_types();
	if ( isset( $allowed[ $ext ] ) ) {
		$data['ext']             = $ext;
		$data['type']            = $allowed[ $ext ];
		$data['proper_filename'] = $filename;
	}
	return $data;
}, 10, 3 );

